package com.gimdropvalues;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.OptionalInt;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses the familiar loot-broadcast and personal valuable-drop sentence forms.
 * The caller must select the parser for the server-generated message channel;
 * neither parser should be used for player-written chat.
 *
 * <p>All matching happens against visible text. Edits remove visible characters
 * only: the original colour, icon and other markup tags stay in their original
 * order, even when this leaves an empty colour span. This avoids corrupting a
 * tag around an item, player name, or the entire message.</p>
 */
public final class BroadcastValueFormatter
{
    private static final String NUMBER = "(?:0|[1-9][0-9]*|[1-9][0-9]{0,2}(?:,[0-9]{3})+)";

    private static final Pattern BROADCAST = Pattern.compile(
        "^\\|?[A-Za-z0-9 _-]{1,12} (?:has )?received "
            + "(?:a (?:rare )?drop|a clue item|special loot from a raid): "
            + "(?<item>[^\\r\\n]+?)"
            + "(?<gap> +)"
            + "(?<price>\\((?<value>" + NUMBER + ") (?<currency>coins?|gp)\\))"
            + "(?<suffix>(?: from [^\\r\\n]+| at " + NUMBER
            + " (?:killcount|XP|permits)[^\\r\\n]*|[.!](?: \\((?:killcount|kc|Kill count):? [^\\r\\n]+\\))?)?)$",
        Pattern.CASE_INSENSITIVE);

    // The game's own report, as exercised by RuneLite's ScreenshotPluginTest.
    // Unlike a clan broadcast this has no player name or source suffix.
    private static final Pattern GAME_DROP = Pattern.compile(
        "^Valuable drop: (?<item>[^\\r\\n]+?)"
            + "(?<gap> +)"
            + "(?<price>\\((?<value>" + NUMBER + ") (?<currency>coins?|gp)\\))"
            + "[.!]?$",
        Pattern.CASE_INSENSITIVE);

    private static final Pattern QUANTITY = Pattern.compile(
        "^(?<quantity>" + NUMBER + ") *[x\\u00d7] *(?<name>.+)$",
        Pattern.CASE_INSENSITIVE);

    private static final Pattern EXTRA_PRICE = Pattern.compile(
        "\\(" + NUMBER + " (?:coins?|gp)\\)", Pattern.CASE_INSENSITIVE);

    private BroadcastValueFormatter()
    {
    }

    /** Parses a GIM/clan loot broadcast; returns empty for other sentence forms. */
    public static Optional<ParsedDrop> parse(String message)
    {
        return parse(message, BROADCAST);
    }

    /**
     * Parses a valuable-drop notice or a named received-drop report in the
     * game's own chat. The caller must restrict this to game-system channels.
     */
    public static Optional<ParsedDrop> parseGameMessage(String message)
    {
        Optional<ParsedDrop> valuableDrop = parse(message, GAME_DROP);
        return valuableDrop.isPresent() ? valuableDrop : parse(message);
    }

    /** Returns empty for an unrecognised or ambiguous sentence. */
    private static Optional<ParsedDrop> parse(String message, Pattern pattern)
    {
        if (message == null || message.isEmpty())
        {
            return Optional.empty();
        }

        VisibleText visible = VisibleText.from(message);
        if (visible == null)
        {
            return Optional.empty();
        }
        Matcher loot = pattern.matcher(visible.text);
        if (!loot.matches())
        {
            return Optional.empty();
        }

        String itemName = loot.group("item").trim();
        long quantity = 1L;
        Matcher amount = QUANTITY.matcher(itemName);
        if (amount.matches())
        {
            try
            {
                quantity = Long.parseLong(amount.group("quantity").replace(",", ""));
            }
            catch (NumberFormatException ex)
            {
                return Optional.empty();
            }
            if (quantity < 1)
            {
                return Optional.empty();
            }
            itemName = amount.group("name").trim();
        }

        // A second price-looking fragment cannot be a single item name. Avoid
        // silently converting only the final price of a compound loot message.
        if (itemName.isEmpty() || itemName.contains(":")
            || EXTRA_PRICE.matcher(itemName).find())
        {
            return Optional.empty();
        }

        return Optional.of(new ParsedDrop(
            message, visible.rawIndexes, itemName, quantity,
            loot.start("gap"), loot.end("price"),
            loot.start("value"), loot.end("currency")));
    }

    /** Immutable parse result. It always retains the original message. */
    public static final class ParsedDrop
    {
        private final String original;
        private final int[] rawIndexes;
        private final String itemName;
        private final long quantity;
        private final int hideStart;
        private final int hideEnd;
        private final int replaceStart;
        private final int replaceEnd;

        private ParsedDrop(String original, int[] rawIndexes, String itemName,
            long quantity, int hideStart, int hideEnd,
            int replaceStart, int replaceEnd)
        {
            this.original = original;
            this.rawIndexes = rawIndexes;
            this.itemName = itemName;
            this.quantity = quantity;
            this.hideStart = hideStart;
            this.hideEnd = hideEnd;
            this.replaceStart = replaceStart;
            this.replaceEnd = replaceEnd;
        }

        public String getItemName()
        {
            return itemName;
        }

        public long getQuantity()
        {
            return quantity;
        }

        /** Broadcasts carry text; an icon tag is never treated as an item ID. */
        public OptionalInt getItemId()
        {
            return OptionalInt.empty();
        }

        public String hideValue()
        {
            return replaceVisible(hideStart, hideEnd, "");
        }

        /** The caller supplies the total for the entire item stack. */
        public String withHighAlchValue(long total)
        {
            if (total < 0)
            {
                throw new IllegalArgumentException("High alchemy value must not be negative");
            }
            return replaceVisible(replaceStart, replaceEnd,
                String.format(Locale.US, "%,d", total) + " gp");
        }

        private String replaceVisible(int start, int end, String replacement)
        {
            StringBuilder output = new StringBuilder(original.length() + replacement.length());
            int cursor = 0;
            for (int visibleIndex = start; visibleIndex < end; visibleIndex++)
            {
                int rawIndex = rawIndexes[visibleIndex];
                output.append(original, cursor, rawIndex);
                if (visibleIndex == start)
                {
                    output.append(replacement);
                }
                cursor = rawIndex + 1;
            }
            output.append(original, cursor, original.length());
            return output.toString();
        }
    }

    private static final class VisibleText
    {
        private final String text;
        private final int[] rawIndexes;

        private VisibleText(String text, int[] rawIndexes)
        {
            this.text = text;
            this.rawIndexes = rawIndexes;
        }

        private static VisibleText from(String raw)
        {
            StringBuilder text = new StringBuilder(raw.length());
            List<Integer> indexes = new ArrayList<>();
            for (int i = 0; i < raw.length(); i++)
            {
                char c = raw.charAt(i);
                if (c == '<')
                {
                    int close = raw.indexOf('>', i + 1);
                    if (close < 0)
                    {
                        return null;
                    }
                    // A line break is real layout/content, not harmless styling.
                    String tag = raw.substring(i + 1, close);
                    if ("br".equalsIgnoreCase(tag) || "lt".equalsIgnoreCase(tag)
                        || "gt".equalsIgnoreCase(tag))
                    {
                        return null;
                    }
                    i = close;
                }
                else
                {
                    text.append(c == '\u00a0' ? ' ' : c);
                    indexes.add(i);
                }
            }
            int[] rawIndexes = new int[indexes.size()];
            for (int i = 0; i < indexes.size(); i++)
            {
                rawIndexes[i] = indexes.get(i);
            }
            return new VisibleText(text.toString(), rawIndexes);
        }
    }
}

package com.gimdropvalues;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(GimDropValuesConfig.GROUP)
public interface GimDropValuesConfig extends Config
{
	String GROUP = "gimdropvalues";

	@ConfigItem(
		keyName = "displayMode",
		name = "Value display",
		description = "Hide the coin value, or show the stack's High Alchemy value before rune costs. "
			+ "If an item cannot be identified reliably, its coin value is hidden.",
		position = 0
	)
	default ValueDisplayMode displayMode()
	{
		return ValueDisplayMode.HIDE;
	}

	@ConfigItem(
		keyName = "groupIronman",
		name = "Group Ironman broadcasts",
		description = "Apply to loot announcements in your Group Ironman chat.",
		position = 1
	)
	default boolean groupIronman()
	{
		return true;
	}

	@ConfigItem(
		keyName = "gameChat",
		name = "Game chat loot reports",
		description = "Apply to personal valuable-drop reports and supported loot announcements in game chat.",
		position = 2
	)
	default boolean gameChat()
	{
		return true;
	}

	@ConfigItem(
		keyName = "clanBroadcasts",
		name = "Clan broadcasts",
		description = "Also apply to loot announcements in your regular clan chat.",
		position = 3
	)
	default boolean clanBroadcasts()
	{
		return false;
	}

	@ConfigItem(
		keyName = "guestClanBroadcasts",
		name = "Guest clan broadcasts",
		description = "Also apply to loot announcements in the clan you are visiting.",
		position = 4
	)
	default boolean guestClanBroadcasts()
	{
		return false;
	}
}

package com.gimdropvalues;

import com.google.inject.Provides;
import java.util.Optional;
import java.util.OptionalLong;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MessageNode;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "GIM Drop Values",
	description = "Hide coin values or show High Alch values in GIM broadcasts and game-chat loot reports",
	tags = {"group", "ironman", "gim", "loot", "drop", "value", "alchemy", "chat"}
)
public class GimDropValuesPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private GimDropValuesConfig config;

	@Inject
	private RuneLiteHighAlchLookup alchLookup;

	@Provides
	GimDropValuesConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GimDropValuesConfig.class);
	}

	@Override
	protected void startUp()
	{
		refresh();
	}

	@Override
	protected void shutDown()
	{
		refresh();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (GimDropValuesConfig.GROUP.equals(event.getGroup()))
		{
			refresh();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			alchLookup.clear();
		}
	}

	/**
	 * Runs after RuneLite's ChatMessageManager (priority 0). This changes only
	 * the text being drawn, leaving MessageNode and ChatMessage events intact.
	 * Switching mode or disabling the plugin therefore also restores old lines.
	 */
	@Subscribe(priority = -10)
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!"chatMessageBuilding".equals(event.getEventName()))
		{
			return;
		}

		int intSize = client.getIntStackSize();
		int objectSize = client.getObjectStackSize();
		int[] ints = client.getIntStack();
		Object[] objects = client.getObjectStack();
		if (ints == null || objects == null || intSize < 1 || intSize > ints.length
			|| objectSize < 2 || objectSize > objects.length || client.getMessages() == null)
		{
			return;
		}

		MessageNode node = client.getMessages().get(ints[intSize - 1]);
		if (node == null || !accepts(node.getType(), config))
		{
			return;
		}
		int messageIndex = objectSize - 2;
		if (!(objects[messageIndex] instanceof String))
		{
			return;
		}

		String message = (String) objects[messageIndex];
		int displayStart = displayStart(message, node.getType());
		String displayedMessage = message.substring(displayStart);
		if (displayedMessage.indexOf('|') >= 0)
		{
			return;
		}
		Optional<BroadcastValueFormatter.ParsedDrop> parsed = isGameMessage(node.getType())
			? BroadcastValueFormatter.parseGameMessage(displayedMessage)
			: BroadcastValueFormatter.parse(displayedMessage);
		if (!parsed.isPresent())
		{
			return;
		}
		BroadcastValueFormatter.ParsedDrop drop = parsed.get();
		String replacement = drop.hideValue();
		if (config.displayMode() == ValueDisplayMode.HIGH_ALCH)
		{
			OptionalLong total = alchLookup.stackValue(drop);
			if (total.isPresent())
			{
				replacement = drop.withHighAlchValue(total.getAsLong());
			}
		}
		objects[messageIndex] = message.substring(0, displayStart) + replacement;
	}

	/**
	 * ChatBuilder removes these fields after chatMessageBuilding: a leading GIM
	 * marker and optional metadata for clan messages, or optional metadata for
	 * game messages. Keep the prefix untouched and parse only the displayed body.
	 * Guest-clan messages and SPAM do not use that metadata-splitting path.
	 */
	private static int displayStart(String message, ChatMessageType type)
	{
		int start = 0;
		if (type == ChatMessageType.CLAN_GIM_MESSAGE || type == ChatMessageType.CLAN_MESSAGE)
		{
			start = message.startsWith("|") ? 1 : 0;
		}
		else if (type != ChatMessageType.GAMEMESSAGE)
		{
			return 0;
		}

		int separator = message.indexOf('|', start);
		return separator >= 0 ? separator + 1 : start;
	}

	static boolean accepts(ChatMessageType type, GimDropValuesConfig configuration)
	{
		if (isGameMessage(type))
		{
			return configuration.gameChat();
		}
		if (type == ChatMessageType.CLAN_GIM_MESSAGE)
		{
			return configuration.groupIronman();
		}
		if (type == ChatMessageType.CLAN_MESSAGE)
		{
			return configuration.clanBroadcasts();
		}
		return type == ChatMessageType.CLAN_GUEST_MESSAGE && configuration.guestClanBroadcasts();
	}

	private static boolean isGameMessage(ChatMessageType type)
	{
		return type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.SPAM;
	}

	private void refresh()
	{
		clientThread.invokeLater(() ->
		{
			alchLookup.clear();
			client.refreshChat();
		});
	}
}

package com.gimdropvalues;

import java.util.List;
import java.util.Locale;
import java.util.OptionalLong;

/** Resolves only exact names, refusing conflicting values instead of guessing. */
final class HighAlchResolver
{
	interface ItemLookup
	{
		List<Candidate> find(String exactName);
	}

	static final class Candidate
	{
		private final String name;
		private final int highAlchValue;

		Candidate(String name, int highAlchValue)
		{
			this.name = name;
			this.highAlchValue = highAlchValue;
		}
	}

	private HighAlchResolver()
	{
	}

	static OptionalLong resolveUnitValue(String itemName, ItemLookup lookup)
	{
		String normalized = normalizeName(itemName);
		if (normalized.isEmpty() || normalized.equals("coins") || normalized.equals("platinum token"))
		{
			// Currency is already money, not an item on which to report spell proceeds.
			return OptionalLong.empty();
		}

		List<Candidate> candidates = lookup.find(itemName);
		if (candidates == null)
		{
			return OptionalLong.empty();
		}

		Long resolved = null;
		for (Candidate candidate : candidates)
		{
			if (candidate == null || !normalized.equals(normalizeName(candidate.name)))
			{
				continue;
			}
			if (candidate.highAlchValue < 0)
			{
				return OptionalLong.empty();
			}
			long value = candidate.highAlchValue;
			if (resolved != null && resolved.longValue() != value)
			{
				return OptionalLong.empty();
			}
			resolved = value;
		}
		return resolved == null ? OptionalLong.empty() : OptionalLong.of(resolved);
	}

	static OptionalLong stackValue(OptionalLong unitValue, long quantity)
	{
		if (!unitValue.isPresent() || unitValue.getAsLong() < 0 || quantity <= 0)
		{
			return OptionalLong.empty();
		}
		try
		{
			return OptionalLong.of(Math.multiplyExact(unitValue.getAsLong(), quantity));
		}
		catch (ArithmeticException ignored)
		{
			return OptionalLong.empty();
		}
	}

	static String normalizeName(String name)
	{
		return name == null ? "" : name.replace('\u00a0', ' ').trim().toLowerCase(Locale.ROOT);
	}
}

package com.gimdropvalues;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import java.util.ArrayList;
import java.util.List;
import java.util.OptionalLong;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;

/** Uses RuneLite's existing item index and game definitions; makes no network requests. */
@Singleton
final class RuneLiteHighAlchLookup
{
	private final ItemManager itemManager;
	private final Cache<String, OptionalLong> unitValues = CacheBuilder.newBuilder()
		.maximumSize(1024)
		.expireAfterWrite(30, TimeUnit.SECONDS)
		.build();

	@Inject
	RuneLiteHighAlchLookup(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	OptionalLong stackValue(BroadcastValueFormatter.ParsedDrop drop)
	{
		String key = HighAlchResolver.normalizeName(drop.getItemName());
		OptionalLong unit = unitValues.getIfPresent(key);
		if (unit == null)
		{
			unit = HighAlchResolver.resolveUnitValue(drop.getItemName(), this::findCandidates);
			// A brief expiry lets an item-index download finish without requiring a restart.
			unitValues.put(key, unit);
		}
		return HighAlchResolver.stackValue(unit, drop.getQuantity());
	}

	void clear()
	{
		unitValues.invalidateAll();
	}

	private List<HighAlchResolver.Candidate> findCandidates(String name)
	{
		String normalized = HighAlchResolver.normalizeName(name);
		List<HighAlchResolver.Candidate> matches = new ArrayList<>();
		for (ItemPrice price : itemManager.search(name))
		{
			if (!normalized.equals(HighAlchResolver.normalizeName(price.getName())))
			{
				continue;
			}
			int id = itemManager.canonicalize(price.getId());
			ItemComposition item = itemManager.getItemComposition(id);
			// Compare the game definition as well as the name in RuneLite's item index.
			matches.add(new HighAlchResolver.Candidate(item.getMembersName(), item.getHaPrice()));
		}
		return matches;
	}
}

package com.gimdropvalues;

public enum ValueDisplayMode
{
	HIDE("Hide coin value"),
	HIGH_ALCH("Show High Alch value");

	private final String label;

	ValueDisplayMode(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.gimdropvalues;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BroadcastValueFormatterTest
{
    private BroadcastValueFormatter.ParsedDrop parse(String input)
    {
        assertTrue("Expected a supported broadcast: " + input,
            BroadcastValueFormatter.parse(input).isPresent());
        return BroadcastValueFormatter.parse(input).get();
    }

    private String visible(String text)
    {
        return text.replaceAll("<[^>]*>", "");
    }

    private BroadcastValueFormatter.ParsedDrop parseGameMessage(String input)
    {
        assertTrue("Expected a supported game drop report: " + input,
            BroadcastValueFormatter.parseGameMessage(input).isPresent());
        return BroadcastValueFormatter.parseGameMessage(input).get();
    }

    @Test
    public void formatsGameValuableDropFromRuneLiteFixture()
    {
        // Official RuneLite ScreenshotPluginTest fixture, with a caller-supplied
        // High Alch value. The game's report normally has no final full stop.
        String input = "<col=ef1020>Valuable drop: Rune scimitar (25,600 coins)</col>";
        BroadcastValueFormatter.ParsedDrop drop = parseGameMessage(input);
        assertEquals("Rune scimitar", drop.getItemName());
        assertEquals(1L, drop.getQuantity());
        assertEquals("<col=ef1020>Valuable drop: Rune scimitar</col>", drop.hideValue());
        assertEquals("<col=ef1020>Valuable drop: Rune scimitar (15,360 gp)</col>",
            drop.withHighAlchValue(15360));
        assertFalse(drop.withHighAlchValue(15360).contains("HA"));
    }

    @Test
    public void formatsGameStackFromRuneLiteFixture()
    {
        // Exact game-report format from RuneLite's ScreenshotPluginTest.
        BroadcastValueFormatter.ParsedDrop drop = parseGameMessage(
            "<col=ef1020>Valuable drop: 6 x Bronze arrow (42 coins)</col>");
        assertEquals("Bronze arrow", drop.getItemName());
        assertEquals(6L, drop.getQuantity());
        assertEquals("<col=ef1020>Valuable drop: 6 x Bronze arrow</col>", drop.hideValue());
        assertEquals("<col=ef1020>Valuable drop: 6 x Bronze arrow (6 gp)</col>",
            drop.withHighAlchValue(6));
    }

    @Test
    public void keepsPersonalItemParenthesesQuantityAndTags()
    {
        String input = "<col=ef1020>Valuable drop: <col=ff9040>2 x Dragon dagger(p++)"
            + "</col> (<col=ffff00>60,002</col> coins).</col>";
        BroadcastValueFormatter.ParsedDrop drop = parseGameMessage(input);
        assertEquals("Dragon dagger(p++)", drop.getItemName());
        assertEquals(2L, drop.getQuantity());
        assertEquals("Valuable drop: 2 x Dragon dagger(p++).", visible(drop.hideValue()));
        assertEquals("Valuable drop: 2 x Dragon dagger(p++) (36,000 gp).",
            visible(drop.withHighAlchValue(36000)));
        assertEquals("<col=ef1020>Valuable drop: <col=ff9040>2 x Dragon dagger(p++)"
            + "</col> (<col=ffff00>36,000 gp</col>).</col>", drop.withHighAlchValue(36000));
    }

    @Test
    public void supportsPersonalCommaQuantitiesAndNonbreakingSpaces()
    {
        BroadcastValueFormatter.ParsedDrop drop = parseGameMessage(
            "Valuable drop: 1,200\u00a0x\u00a0Nature rune\u00a0(100,000 coins)");
        assertEquals("Nature rune", drop.getItemName());
        assertEquals(1200L, drop.getQuantity());
        assertEquals("Valuable drop: 1,200\u00a0x\u00a0Nature rune", drop.hideValue());
    }

    @Test
    public void keepsPersonalPrefixOutOfBroadcastParser()
    {
        assertFalse(BroadcastValueFormatter.parse(
            "Valuable drop: Rune platebody (39,000 coins)").isPresent());
    }

    @Test
    public void supportsPriceBearingReceivedDropReportsInGameChat()
    {
        // RuneLite's ChatNotificationsPluginTest uses GAMEMESSAGE for a named
        // received-drop report. These valued variants are constructed fixtures.
        BroadcastValueFormatter.ParsedDrop named = parseGameMessage(
            "Logic Knot received a drop: Adamant longsword (3,200 coins).");
        assertEquals("Adamant longsword", named.getItemName());
        assertEquals("Logic Knot received a drop: Adamant longsword.", named.hideValue());
        assertEquals("Logic Knot received a drop: Adamant longsword (1,920 gp).",
            named.withHighAlchValue(1920));

        BroadcastValueFormatter.ParsedDrop own = parseGameMessage(
            "You received a drop: 2 x Rune platebody (100,000 coins).");
        assertEquals("Rune platebody", own.getItemName());
        assertEquals(2L, own.getQuantity());
        assertEquals("You received a drop: 2 x Rune platebody (78,000 gp).",
            own.withHighAlchValue(78000));
    }

    @Test
    public void rejectsUnrelatedValuelessOrAmbiguousGameMessages()
    {
        String[] inputs = {
            "Untradeable drop: Rusty sword",
            "<col=ef1020>Untradeable drop: Rusty sword",
            "Valuable drop: Rune platebody",
            "Your loot is worth around 100,000 coins.",
            "Your treasure is worth around 100,000 coins!",
            "You have been awarded 100,000 coins.",
            "New item added to your collection log: Rune platebody",
            "Jurad: Valuable drop: Rune platebody (39,000 coins)",
            "Valuable drop: Rune platebody (1,23 coins)",
            "Valuable drop: Rune platebody (39,000 coins). unrelated text",
            "Valuable drop: Rune platebody (39,000 coins), Rune sword (12,000 coins)",
            "Valuable drop: Rune platebody (39,000 coins)<br>Second line",
            "Valuable drop: Rune platebody (39,000 coins)<unclosed",
            "Valuable drop: 0 x Rune platebody (39,000 coins)",
